def rotate_90(matrix: list[list[int]]) -> list[list[int]]:
    n = len(matrix)
    rotated = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            rotated[n - 1 - j][i] = matrix[i][j]
    return rotated

