def word_frequency(text: str) -> dict[str, int]:
    import string
    text = text.lower()
    words = text.split()
    frequency = {}
    for word in words:
        word = word.strip(string.punctuation)
        if word:
            frequency[word] = frequency.get(word, 0) + 1
    return frequency
